#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later
"""Compile regression shaders offline and embed them as a C++ header.

Every generate_*.py beside this module names its shaders and calls generate().
Each shader is compiled with glslc for Vulkan 1.1 from tests/unit/gpu/shaders,
optionally rewritten and validated, and written as a constexpr word array.
"""

from __future__ import annotations

__import__("sys").dont_write_bytecode = True

import argparse
from dataclasses import dataclass
from pathlib import Path
import struct
import subprocess
import tempfile
from typing import Callable, Iterable, Sequence


SHADERS = Path(__file__).resolve().parents[2] / "unit/gpu/shaders"


@dataclass(frozen=True)
class Shader:
    """One embedded array: its C++ name, source file and extra glslc flags."""

    name: str
    source: str
    flags: Sequence[str] = ()
    # Edits the compiled words in place before validation and embedding.
    rewrite: Callable[[list[int]], None] | None = None


def generate(
    generator: str,
    description: str,
    header: str,
    shaders: Iterable[Shader],
    *,
    optimization: str = "-O",
    namespace: str | None = None,
    validator: bool = False,
) -> None:
    """Parse the generator's options and write tests/unit/gpu/shaders/header.

    generator is the calling script's file name, recorded in the header.
    validator adds --spirv-val, an optional offline SPIR-V validator.
    """
    parser = argparse.ArgumentParser(description=description)
    parser.add_argument("--glslc", default="glslc")
    if validator:
        parser.add_argument("--spirv-val", help="optional offline SPIR-V validator")
    options = parser.parse_args()
    output = ["// SPDX-License-Identifier: GPL-2.0-or-later",
              f"// Generated by tests/tooling/gpu/{generator}; do not edit.",
              "#pragma once", "#include <array>", "#include <cstdint>"]
    if namespace is not None:
        output.append(f"namespace {namespace} {{")
    output.append("")
    with tempfile.TemporaryDirectory(prefix=f"{Path(header).stem}-") as temporary:
        for index, shader in enumerate(shaders):
            binary = Path(temporary) / f"{index}.spv"
            subprocess.run([options.glslc, "--target-env=vulkan1.1", optimization,
                            *shader.flags, str(SHADERS / shader.source),
                            "-o", str(binary)], check=True)
            data = binary.read_bytes()
            words = list(struct.unpack(f"<{len(data) // 4}I", data))
            if shader.rewrite is not None:
                shader.rewrite(words)
                binary.write_bytes(struct.pack(f"<{len(words)}I", *words))
            if validator and options.spirv_val:
                subprocess.run([options.spirv_val, "--target-env", "vulkan1.1",
                                str(binary)], check=True)
            output.append(f"constexpr std::array<uint32_t, {len(words)}> {shader.name}{{")
            for start in range(0, len(words), 6):
                output.append("    " + ", ".join(f"0x{word:08x}"
                              for word in words[start:start + 6]) + ",")
            output.extend(["};", ""])
    if namespace is not None:
        output.extend([f"}} // namespace {namespace}", ""])
    (SHADERS / header).write_text("\n".join(output))
